// Runs inside the 24h customer-service window opened by the subscriber's reply
// (e.g. tapping the welcome template's quick-reply button). Free-form text,
// audio and video are allowed here. Payload is forwarded + HMAC-signed by the
// Next.js WhatsApp webhook, which already resolved the subscriber (goal/lang).
const crypto = require('crypto');
const secret = $env.N8N_SHARED_SECRET;
const raw = JSON.stringify($json.body);
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
const got = $json.headers['x-ostentaculus-signature'] || '';
const a = Buffer.from(expected); const b = Buffer.from(got);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) { throw new Error('Invalid ingress signature'); }

const p = $json.body;
const phone = String(p.phone || p.from || '').replace(/\D/g, '');
if (!phone) throw new Error('phone missing');
const lang = (p.lang === 'es') ? 'es' : 'pt';
const goalRaw = ['sono', 'ansiedade', 'foco'].includes(p.goal) ? p.goal : 'default';
const key = goalRaw.toUpperCase();            // SONO | ANSIEDADE | FOCO | DEFAULT
const L = lang.toUpperCase();                 // PT | ES
const first = String(p.name || '').trim().split(' ')[0] || (lang === 'es' ? '' : '');

// Personalised opening line by goal + language.
const LINES = {
  pt: {
    sono:      'Que bom te ver por aqui 🌙 Vamos começar pelo seu sono. Ouça este áudio deitado, hoje à noite:',
    ansiedade: 'Respire fundo — você chegou 💙 Vamos começar baixando a ansiedade. Ouça este áudio agora:',
    foco:      'Bora começar 🎯 Vamos treinar o seu foco. Ouça este áudio antes da próxima tarefa:',
    default:   'Que bom te ver por aqui 🌙 Preparei algo para você começar. Ouça este áudio:'
  },
  es: {
    sono:      'Qué bien tenerte aquí 🌙 Empezamos por tu sueño. Escucha este audio tumbado, esta noche:',
    ansiedade: 'Respira hondo — has llegado 💙 Empezamos bajando la ansiedad. Escucha este audio ahora:',
    foco:      'Vamos a empezar 🎯 Entrenamos tu foco. Escucha este audio antes de tu próxima tarea:',
    default:   'Qué bien tenerte aquí 🌙 Preparé algo para empezar. Escucha este audio:'
  }
};
const text = LINES[lang][goalRaw] || LINES[lang].default;
const audioUrl = $env['PX_AUDIO_' + key + '_' + L] || $env['PX_AUDIO_DEFAULT_' + L];
const videoUrl = $env['PX_VIDEO_' + key + '_' + L] || $env['PX_VIDEO_DEFAULT_' + L];
const videoCaption = lang === 'es' ? 'Tu primera práctica guiada 🎬' : 'Sua primeira prática guiada 🎬';
return [{ json: { phone, lang, goal: goalRaw, text, audioUrl, videoUrl, videoCaption } }];
